-- Guard invariants even when an application query is malformed.
CREATE TRIGGER users_role_insert BEFORE INSERT ON users WHEN NEW.role NOT IN ('STUDENT','RECIPIENT','ADMINISTRATOR') BEGIN SELECT RAISE(ABORT, 'Invalid role'); END;
CREATE TRIGGER users_role_update BEFORE UPDATE OF role ON users WHEN NEW.role NOT IN ('STUDENT','RECIPIENT','ADMINISTRATOR') BEGIN SELECT RAISE(ABORT, 'Invalid role'); END;
CREATE TRIGGER request_state_insert BEFORE INSERT ON share_requests WHEN NEW.status NOT IN ('PENDING','APPROVED','REJECTED') OR NEW.durationHours < 1 OR NEW.durationHours > 720 BEGIN SELECT RAISE(ABORT, 'Invalid request state or duration'); END;
CREATE TRIGGER request_state_update BEFORE UPDATE OF status ON share_requests WHEN NEW.status NOT IN ('PENDING','APPROVED','REJECTED') OR (OLD.status <> 'PENDING' AND NEW.status <> OLD.status) BEGIN SELECT RAISE(ABORT, 'Invalid request transition'); END;
CREATE TRIGGER grant_relationship_insert BEFORE INSERT ON share_grants WHEN NEW.ownerId <> (SELECT ownerId FROM documents WHERE id = NEW.documentId) OR NEW.ownerId <> (SELECT studentId FROM share_requests WHERE id = NEW.requestId) OR NEW.recipientId <> (SELECT recipientId FROM share_requests WHERE id = NEW.requestId) OR NEW.expiresAt <= NEW.consentAt BEGIN SELECT RAISE(ABORT, 'Invalid grant relationship or expiry'); END;
CREATE TRIGGER proposal_immutable BEFORE UPDATE OF proposerId, proposedMaxHours, previousMaxHours, baseVersion, reason, proposalHash ON admin_change_requests BEGIN SELECT RAISE(ABORT, 'Proposal is immutable; create a new proposal'); END;
CREATE TRIGGER proposal_decision BEFORE UPDATE OF status, reviewerId ON admin_change_requests WHEN NEW.reviewerId = NEW.proposerId OR OLD.status <> 'PENDING' OR NEW.status NOT IN ('APPLIED','REJECTED') BEGIN SELECT RAISE(ABORT, 'Independent final decision required'); END;
CREATE TRIGGER policy_bound_insert BEFORE INSERT ON policies WHEN NEW.maxDurationHours < 1 OR NEW.maxDurationHours > 720 BEGIN SELECT RAISE(ABORT, 'Policy outside bounded demo scope'); END;
CREATE TRIGGER policy_bound_update BEFORE UPDATE ON policies WHEN NEW.maxDurationHours < 1 OR NEW.maxDurationHours > 720 OR NEW.version <> OLD.version + 1 BEGIN SELECT RAISE(ABORT, 'Invalid policy version or bounds'); END;
